            self.views.chat_input.clone().into_any_element()
        } else {
            redrawing::cached(&self.views.chat_input, cx)
        };
        let column = v_flex()
            .size_full()
            .child(top)
            .when(!hidden, |column| column.child(chat_input));
        self.with_referenced_spec(column, window, cx)
    }
}

