        // heights, so rows it hasn't laid out need a guess there too.
        if std::mem::take(&mut heights.hint) {
            let guess = heights.guess();
            drop(heights);
            self.state.clone().with_uniform_item_height(guess);
            heights = self.heights.borrow_mut();
        }

