        let space = size(AvailableSpace::Definite(width), AvailableSpace::MinContent);
        let deadline = Instant::now() + MEASURE_BUDGET;
        let mut measured = 0;
        loop {
            let next = heights.next;
            let Some(ix) = heights.rows[next.min(count)..]
                .iter()
                .position(|row| !row.exact)
                .map(|at| next + at)
